package io.knowledgebrain.content;
import java.time.*;import java.util.*;import jakarta.servlet.http.Cookie;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import org.junit.jupiter.api.*;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class AttachmentApiTest {
 NoteStore store;SpaceAuthorizationClient authority;MediaAvailabilityClient media;NoteAttachmentsController api;UUID space,actor,note;
 @BeforeEach void setup(){store=mock(NoteStore.class);authority=mock(SpaceAuthorizationClient.class);media=mock(MediaAvailabilityClient.class);var metrics=new SimpleMeterRegistry();api=new NoteAttachmentsController(store,new NoteController(store,authority,metrics,"https://localhost:8443"),media,metrics);var ids=new UuidV7(Clock.systemUTC());space=ids.next();actor=ids.next();note=ids.next();when(authority.authorize(eq(space),eq("a".repeat(43)),anyBoolean(),anyString())).thenReturn(actor);}
 MockHttpServletRequest request(){var r=new MockHttpServletRequest("PUT","/");r.setSecure(true);r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));r.addHeader("Origin","https://localhost:8443");r.addHeader("If-Match","\"a0\"");r.setContentType("application/json");r.setContent("{\"mediaIds\":[]}".getBytes());return r;}
 @Test void invalidEtagsAndDuplicateTrailingBodiesNeverReachMedia(){var missing=request();missing.removeHeader("If-Match");assertThatThrownBy(()->api.replace(space,note,missing)).isInstanceOf(ResponseStatusException.class);for(String body:List.of("{}","{\"mediaIds\":[],\"mediaIds\":[]}","{\"mediaIds\":[]} {}")){var r=request();r.setContent(body.getBytes());assertThatThrownBy(()->api.replace(space,note,r)).isInstanceOf(ResponseStatusException.class);}verifyNoInteractions(store,media);}
 @Test void unavailableMediaAuthorityCannotMutateRelations(){when(media.check(eq(space),anyList(),anyString())).thenThrow(new ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE));assertThatThrownBy(()->api.replace(space,note,request())).isInstanceOf(ResponseStatusException.class);verify(store,never()).attachments(any(),any(),any(),anyLong(),anyList(),anyString());}
}
